'use strict';

var Row = require('../src/row');

var simpleRow = require('./fixtures/simple_row');
var overrideRow = require('./fixtures/override_row');
var panelData = {
    foo: 'foo',
    bar: 'bar',
    baz: 1,
};

test('Simple row', function () {
    var row = new Row();
    expect(row.generate()).toEqual(simpleRow);
});

test('Row with overriden information', function () {
    var panel1 = {
        generate: function generate() {
            return panelData;
        },
    };
    var row = new Row({
        title: 'My Row',
        height: '1000px',
        editable: false,
        collapse: true,
        // @ts-expect-error incomplete mock
        panels: [panel1],
    });
    expect(row.generate()).toEqual(overrideRow);
});

test('Add panels to row when passed', function () {
    var panel1 = {
        foo: 'foo',
        bar: 'bar',
        baz: 1,
    };
    var panel2 = {
        foo: 'foo2',
        bar: 'bar2',
        baz: 2,
    };
    var row = new Row({
        // @ts-expect-error incomplete mock
        panels: [panel1, panel2],
    });

    expect(row.state.panels).toEqual([panel1, panel2]);
});

test('Row can add panels', function () {
    var row = new Row({
        title: 'My Row',
        height: '1000px',
        editable: false,
        collapse: true,
    });
    var panel1 = {
        foo: 'foo',
        bar: 'bar',
        baz: 1,
    };
    var panel2 = {
        foo: 'foo2',
        bar: 'bar2',
        baz: 2,
    };

    // @ts-expect-error bad mock type
    row.addPanel(panel1);
    // @ts-expect-error bad mock type
    row.addPanel(panel2);
    expect(row.panels).toEqual([panel1, panel2]);
});

test('Row generates state', function () {
    var panel = {
        generate: function generate() {
            return panelData;
        },
    };
    var row = new Row({
        title: 'My Row',
        height: '1000px',
        editable: false,
        collapse: true,
        // @ts-expect-error incomplete mock
        panels: [panel],
    });

    expect(row.generate()).toEqual(overrideRow);
});

