'use strict';

var config = require('../src/config');

test('config extends default configuration', function () {
    var foo = 'foo';
    var bar = 1;
    var user = 'notguest';
    var group = 'guest';
    var url = 'http://myfakeurl.com';
    var cookie = 'auth=value';
