        },
        evaluator: {
            type: 'gt',
            params: [1.1],
        },
        operator: {
            type: 'and',
        },
    });

    const overrideConditions = { conditions: [condition] };
    const alert = new Alert(overrideConditions);

    expect(alert.generate()).toEqual(alertWithCondition);
});

